<script setup>
import {computed,ref} from 'vue';
import {Head,router,usePage} from '@inertiajs/vue3';
import {Bot,BrainCircuit,Database,FileCode2,Bug,LayoutDashboard,History,Send,ShieldCheck,Trash2,CheckCircle2} from 'lucide-vue-next';
const page=usePage();
const props=defineProps({runs:{type:Array,default:()=>[]},config:{type:Object,default:()=>({demo_mode:true,model:'gpt-5.6-luna'})}});
const taskType=ref('requirement'),title=ref(''),requirement=ref(''),processing=ref(false),selectedRun=ref(null);
const taskOptions=[['requirement','Requirement Analysis'],['database','Database Schema'],['crud','Laravel CRUD'],['api','API Planning'],['bug','Bug Analysis'],['vue','Vue Component'],['documentation','Documentation'],['testing','Testing Checklist']];
const examples={requirement:'I need an LMS with Admin, Instructor and Student roles, courses, lessons, quizzes, payments and student progress.',database:'Design a database for a service booking platform with customers, services, bookings, staff and payments.',crud:'Create a Product CRUD with name, SKU, price, stock quantity, category, image and active status.',api:'Create REST APIs for customer management with search, filtering, pagination and validation.',bug:'SQLSTATE[42S22]: Column not found: 1054 Unknown column status in where clause. The dashboard request fails.',vue:'Create a responsive customer table with search, filters, pagination, loading, empty state and delete confirmation.',documentation:'Write technical documentation for a Laravel 12 + Vue 3 + Inertia customer management module.',testing:'Create a complete test checklist for an authenticated CRUD application with roles and permissions.'};
const flashRun=computed(()=>page.props.flash?.ai_run||null),errors=computed(()=>page.props.errors||{}),outputRun=computed(()=>flashRun.value||selectedRun.value),recentRuns=computed(()=>props.runs||[]);
function useExample(type=taskType.value){requirement.value=examples[type];title.value=taskOptions.find(x=>x[0]===type)?.[1]||'';}
function runEmployee(){if(requirement.value.trim().length<10||processing.value)return;processing.value=true;router.post('/ai-employee/run',{task_type:taskType.value,title:title.value,requirement:requirement.value},{preserveScroll:true,onSuccess:()=>selectedRun.value=null,onFinish:()=>processing.value=false});}
function showRun(run){selectedRun.value=run} function deleteRun(run){if(!confirm('Delete this run?'))return;router.delete(`/ai-runs/${run.id}`,{preserveScroll:true});if(selectedRun.value?.id===run.id)selectedRun.value=null}
</script>
<template><Head title="AI Employee Dashboard"/><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">D</div><div><h1>DevPilot AI</h1><small>Web Dev Employee</small></div></div><div class="nav-label">Workspace</div><div class="nav-item active"><LayoutDashboard :size="16"/> AI Workspace</div><div class="nav-item"><History :size="16"/> Run History</div><div class="nav-item"><ShieldCheck :size="16"/> Verification</div><div class="sidebar-footer"><strong style="color:#aeb6c6">Human-in-the-loop</strong><br>AI drafts. Developer reviews, tests and approves.</div></aside><main class="main"><div class="topbar"><div><div class="eyebrow">AI Employee</div><h2>Development Command Center</h2></div><div class="status-pill"><span class="dot"></span>{{config.demo_mode?'Demo mode':'Live AI'}}</div></div><section class="hero"><div class="hero-grid"><div><h3>Build faster. Verify everything.</h3><p>Turn requirements, database ideas, API tasks, bugs and Vue requests into structured development output. The AI accelerates repetitive work while the developer keeps final control.</p></div><div class="stats"><div class="stat"><strong>{{recentRuns.length}}</strong><span>Saved runs</span></div><div class="stat"><strong>8</strong><span>Employee skills</span></div><div class="stat"><strong>{{config.demo_mode?'Demo':'Live'}}</strong><span>AI provider</span></div></div></div></section><div class="workspace"><section class="card"><div class="card-head"><h4>Assign a development task</h4><span>Model: {{config.model}}</span></div><div class="card-body"><div v-if="errors.ai" class="error">{{errors.ai}}</div><div class="field"><label>Employee skill</label><select v-model="taskType"><option v-for="item in taskOptions" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></div><div class="field"><label>Task title</label><input v-model="title" placeholder="e.g. LMS requirement analysis"></div><div class="field"><label>Requirement / error / development context</label><textarea v-model="requirement" placeholder="Describe what you need the AI Employee to do..."></textarea><div class="quick-grid"><button v-for="item in taskOptions.slice(0,4)" :key="item[0]" class="quick" @click="taskType=item[0];useExample(item[0])">{{item[1]}}</button></div></div><button class="primary" :disabled="processing||requirement.trim().length<10" @click="runEmployee"><span v-if="processing">Running AI Employee…</span><span v-else><Send :size="14" style="vertical-align:-2px"/> Run Employee</span></button></div></section><section class="card"><div class="card-head"><h4>Employee output</h4><span v-if="outputRun">{{outputRun.mode}} · {{outputRun.duration_ms}}ms</span></div><div class="card-body output"><div v-if="!outputRun" class="empty"><div><div class="empty-icon"><Bot :size="25"/></div><strong style="color:#aeb6c6">No output yet</strong><p>Give DevPilot a real development task to generate an implementation plan.</p></div></div><div v-else class="markdown"><div style="display:flex;gap:8px;align-items:center;margin-bottom:15px;color:#6ee7b7;font-size:11px"><CheckCircle2 :size="14"/> Output generated — human verification required</div>{{outputRun.output}}</div></div></section></div><section class="card run-list"><div class="history-head"><div><h4>Recent employee runs</h4><small>Your completed tasks appear here as evidence.</small></div></div><div v-if="recentRuns.length===0" style="padding:24px;color:#697385;font-size:13px">No saved runs yet.</div><div v-for="run in recentRuns" :key="run.id" class="run-item"><div class="run-icon"><Bot :size="16"/></div><div class="run-main" @click="showRun(run)"><strong>{{run.title}}</strong><small>{{run.task_type}} · {{new Date(run.created_at).toLocaleString()}} · {{run.duration_ms||0}}ms</small></div><span class="mode">{{run.mode}}</span><button class="clear-btn" @click="deleteRun(run)" title="Delete"><Trash2 :size="14"/></button></div></section></main></div></template>
